const rgb = (hex) => { const c = parseInt(hex.slice(1), 16); return { r: (c >> 16 & 255) / 255, g: (c >> 8 & 255) / 255, b: (c & 255) / 255 } }
for (const f of [{ family: 'Pretendard', style: 'Regular' }, { family: 'Pretendard', style: 'Medium' }, { family: 'Pretendard', style: 'SemiBold' }, { family: 'Pretendard', style: 'Bold' }]) await figma.loadFontAsync(f)
const weightStyle = (fw) => fw >= 700 ? 'Bold' : fw >= 600 ? 'SemiBold' : fw >= 500 ? 'Medium' : 'Regular'

const page = figma.root.children.find(p => p.name === 'Design System - work')
if (!page) { figma.notify('Design System - work 페이지 없음'); throw new Error('no page') }
await figma.setCurrentPageAsync(page)

const SECTION_NAME = 'Buttons 인벤토리 — 코드 전수 (2026-08-08)'
const prev = page.children.find(n => n.type === 'SECTION' && n.name === SECTION_NAME)
if (prev) prev.remove()
const section = figma.createSection()
section.name = SECTION_NAME
page.appendChild(section)

function specimenCard(d) {
  const card = figma.createFrame()
  card.name = d.label
  card.layoutMode = 'VERTICAL'
  card.itemSpacing = 8
  card.paddingTop = 12; card.paddingBottom = 12; card.paddingLeft = 12; card.paddingRight = 12
  card.primaryAxisSizingMode = 'AUTO'
  card.counterAxisSizingMode = 'FIXED'
  card.resize(360, 100)
  card.fills = [{ type: 'SOLID', color: rgb('#FFFFFF') }]
  card.cornerRadius = 8
  card.strokes = [{ type: 'SOLID', color: rgb('#EAE5E1') }]; card.strokeWeight = 1

  // 버튼 렌더
  const s = d.spec
  const btn = figma.createFrame()
  btn.name = 'render'
  btn.layoutMode = 'HORIZONTAL'
  btn.primaryAxisAlignItems = 'CENTER'
  btn.counterAxisAlignItems = 'CENTER'
  const px = s.px != null ? s.px : 12
  btn.paddingLeft = px; btn.paddingRight = px
  if (s.bg === 'none') btn.fills = []
  else if (s.bg === 'unknown') btn.fills = [{ type: 'SOLID', color: rgb('#FF00FF'), opacity: 0.3 }]
  else { btn.fills = [{ type: 'SOLID', color: rgb(s.bg || '#FFFFFF'), opacity: s.bgA != null ? s.bgA : 1 }] }
  if (s.border) { btn.strokes = [{ type: 'SOLID', color: rgb(s.border) }]; btn.strokeWeight = 1 }
  if (s.shadow) btn.effects = [{ type: 'DROP_SHADOW', color: { r: 0, g: 0, b: 0, a: 0.12 }, offset: { x: 0, y: 2 }, radius: 8, visible: true, blendMode: 'NORMAL' }]

  const t = figma.createText()
  t.fontName = { family: 'Pretendard', style: weightStyle(s.fw || 500) }
  t.fontSize = s.fs || 14
  t.characters = d.label
  t.fills = [{ type: 'SOLID', color: rgb(s.text || '#0C0A08') }]
  btn.appendChild(t)

  const w = s.w != null ? s.w : null
  const h = s.h != null ? s.h : Math.max(24, (s.fs || 14) + 2 * (s.py != null ? s.py : 6))
  btn.primaryAxisSizingMode = w != null ? 'FIXED' : 'AUTO'
  btn.counterAxisSizingMode = 'FIXED'
  btn.resize(w != null ? w : Math.max(40, btn.width), h)
  btn.cornerRadius = s.round ? h / 2 : Math.min(s.r != null ? s.r : 0, h / 2)
  card.appendChild(btn)

  // 메타
  const meta = figma.createText()
  meta.fontName = { family: 'Pretendard', style: 'Regular' }
  meta.fontSize = 10
  const lines = [
    d.k + (s.primitive ? ' · ' + s.primitive : '') + ' · ' + d.n + '곳',
    d.desc,
    ...d.src, ...(d.more ? ['외 ' + d.more + '곳'] : []),
    ...(d.notes.length ? d.notes.map(n => '⚠ ' + n) : []),
  ]
  meta.characters = lines.join('\n')
  meta.fills = [{ type: 'SOLID', color: rgb('#726B65') }]
  card.appendChild(meta)
  meta.layoutSizingHorizontal = 'FILL'
  return card
}

// 그룹별 컬럼 배치
const groups = [...new Set(DATA.map(d => d.g))].sort()
const COL_W = 380, GAP = 40, PER_COL = 18
let colX = 60, maxY = 0
for (const g of groups) {
  const items = DATA.filter(d => d.g === g)
  const header = figma.createText()
  header.fontName = { family: 'Pretendard', style: 'Bold' }
  header.fontSize = 18
  header.characters = g.slice(2) + ' (' + items.length + '종 / ' + items.reduce((a, b) => a + b.n, 0) + '곳)'
  header.fills = [{ type: 'SOLID', color: rgb('#0C0A08') }]
  section.appendChild(header)
  header.x = colX; header.y = 40
  let y = 80, sub = 0
  for (let i = 0; i < items.length; i++) {
    if (i > 0 && i % PER_COL === 0) { sub++; y = 80 }
    const card = specimenCard(items[i])
    section.appendChild(card)
    card.x = colX + sub * (COL_W + 20); card.y = y
    y += card.height + 16
    if (y > maxY) maxY = y
  }
  colX += (sub + 1) * (COL_W + 20) - 20 + GAP
}
section.resizeWithoutConstraints(colX + 60, maxY + 120)
figma.viewport.scrollAndZoomIntoView([section])
figma.notify('버튼 인벤토리 ' + DATA.length + '종 (' + 301 + '곳) 렌더 완료')
